        const tr = ev.target.closest('[data-feat]'); if (tr) { const f = S.project.site.features.find(x => x.id === tr.dataset.feat); if (f?.kind === 'existing-tree') { S.drag = { tree: f.id, from: [...f.position_m], moved: false }; svg.setPointerCapture(ev.pointerId); return; } }
        const bd = ev.target.closest('[data-bed]');
